const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let source='actual',path='all',epoch=0,last=null;
const names={actual:'Real journeys',sample:'Fictional samples',qa:'QA tests'};
export function activityStatisticsPage(){return `<div class="wrap"><section class="page-intro"><span class="eyebrow">Approach 2 · choice statistics</span><h1>What we offer.<br>What people explore.</h1><p class="lede">Compare pathways actually shown with pathways explored and options saved. A save means curiosity, not a commitment.</p></section><div class="tools"><label><span class="field-label">Activity population</span><select id="activity-source">${Object.entries(names).map(([id,label])=>`<option value="${id}" ${source===id?'selected':''}>${label}</option>`).join('')}</select></label><button class="button secondary small" data-refresh-activity>Refresh choice statistics</button></div><div id="activity-statistics-result" aria-live="polite"><p>Loading recorded choices…</p></div><p class="note">Real journeys, fictional samples and QA runs are separate. The earlier 2,000-model study contains suggestions and simulated answers; it has no recorded downstream choices and is not pooled into these rates. Counts describe prototype behavior, not match accuracy or student success.</p><p><a href="#/pathways">Explore pathways ↗</a> · <a href="#/about">How choice recording works ↗</a></p></div>`;}
function content(d){
 const t=d.totals,max=Math.max(1,...d.pathways.flatMap(p=>[p.offeredJourneys,p.exploredJourneys,p.shortlistedJourneys]));
 const metric=(label,value)=>`<div class="panel"><span>${label}</span><strong>${Number(value).toLocaleString()}</strong></div>`;
 const bar=(n,color)=>`<div class="choice-frequency" aria-label="${n}"><span style="width:${Math.max(0,Math.min(100,n/max*100))}%;background:${color}"></span></div>`;
 const rows=d.pathways.slice().sort((a,b)=>b.offeredJourneys-a.offeredJourneys||b.shortlistedJourneys-a.shortlistedJourneys||a.pathway.localeCompare(b.pathway));
 const lower=d.lowerOptions.filter(r=>path==='all'||r.pathId===path).sort((a,b)=>b.savedJourneys-a.savedJourneys||a.option.localeCompare(b.option));
 return `<p class="subtle">${h(names[d.source])} · updated ${h(new Date(d.generatedAt).toLocaleString())}. Journeys are browser drafts, not verified unique people.</p>${!t.journeys?`<p class="note">No ${d.source==='actual'?'real-journey':h(names[d.source]).toLowerCase()} activity recorded yet. Recording is enabled; there are no historical choices to reconstruct.</p>`:''}<div class="choice-stat-grid">${metric('Recorded journeys',t.journeys)}${metric('Shown suggestions',t.withSuggestions)}${metric('Explored a pathway',t.pathwayExplorers)}${metric('Shortlisted at least once',t.shortlisters)}${metric('Saved a program / major',t.majorSavers)}${metric('Saved a career possibility',t.careerSavers)}</div><section class="panel"><h2>Suggestions and pathway choices</h2><p>Distinct journeys per pathway. A journey may appear in several rows. “After offer” links the save to a previously displayed suggestion list containing that pathway; it does not establish that the suggestion caused the save.</p><div class="choice-stat-scroll"><table class="choice-stat-table"><thead><tr><th>College pathway</th><th>Offered</th><th>Explored</th><th>Shortlisted at least once</th><th>Shortlisted after offer</th><th>Offer → shortlist</th><th>Current observed shortlist</th><th>Imported existing shortlist</th></tr></thead><tbody>${rows.map(p=>`<tr><th scope="row"><a href="#/path/${p.pathId}">${h(p.pathway)}</a></th><td>${p.offeredJourneys}${bar(p.offeredJourneys,'#6590bb')}</td><td>${p.exploredJourneys}${bar(p.exploredJourneys,'#b78b3b')}</td><td>${p.shortlistedJourneys}${bar(p.shortlistedJourneys,'#216553')}</td><td>${p.shortlistedAfterOffer}</td><td>${p.offerToShortlistRate===null?'Not available':(p.offerToShortlistRate*100).toFixed(1)+'%'}</td><td>${p.currentShortlists}</td><td>${p.importedShortlists}</td></tr>`).join('')}</tbody></table></div><p class="subtle">Conversion denominator: journeys offered this pathway. Numerator: those with an observed shortlist action linked to that offer. Saves from browsing without a recorded offer remain outside the conversion numerator. Imported options do not count as new actions.</p></section><section class="panel"><h2>Programs and careers explicitly saved</h2><label><span class="field-label">Pathway for lower options</span><select id="activity-path-filter"><option value="all">All pathways</option>${d.pathways.map(p=>`<option value="${p.pathId}" ${path===p.pathId?'selected':''}>${h(p.pathway)}</option>`).join('')}</select></label>${lower.length?`<div class="choice-stat-scroll"><table class="choice-stat-table"><thead><tr><th>Pathway</th><th>Option</th><th>Type</th><th>Saved at least once · journeys</th><th>Currently saved</th><th>Imported choices</th><th>Remove actions</th></tr></thead><tbody>${lower.map(r=>`<tr><td>${h(r.pathway)}</td><td>${h(r.option)}<br><small>${h(r.code)}</small></td><td>${r.kind==='program'?'Program / major':'Career possibility'}</td><td>${r.savedJourneys}</td><td>${r.currentChoices}</td><td>${r.importedChoices}</td><td>${r.removals}</td></tr>`).join('')}</tbody></table></div>`:'<p class="subtle">No program or career saves recorded in this population and pathway filter yet.</p>'}<p class="subtle">Only explicit “Save to my plan” actions count as new choices. Exploring connections or opening career details is tracked separately. Removing an option updates current choices and retains its observed history.</p></section>`;
}
export async function loadActivityStatistics(){
 const seq=++epoch,population=source,box=document.querySelector('#activity-statistics-result');if(!box)return;
 box.innerHTML='<p>Loading recorded choices…</p>';
 try{const r=await fetch('/api/statistics?source='+encodeURIComponent(population),{credentials:'same-origin',cache:'no-store'});if(!r.ok)throw Error('unavailable');const d=await r.json();if(seq!==epoch||population!==source||!box.isConnected)return;if(d.schemaVersion!==1||!Array.isArray(d.pathways)||!Array.isArray(d.lowerOptions))throw Error('invalid');last=d;box.innerHTML=content(d);}
 catch{if(seq===epoch&&box.isConnected)box.innerHTML='<p class="error">Choice statistics could not be loaded. No zero counts have been substituted. Use Refresh to try again.</p>';}
}
export function setActivityStatisticsSource(value){if(!Object.hasOwn(names,value))return;source=value;path='all';return loadActivityStatistics();}
export function setActivityStatisticsPath(value){if(!last||value!=='all'&&!last.pathways.some(p=>p.pathId===value))return;path=value;const box=document.querySelector('#activity-statistics-result');if(box)box.innerHTML=content(last);}
